#include <stdio.h> // Include standard input/output library

int ctr[101]; // Declare an array 'ctr' of size 101 to count occurrences
int num; // Declare a variable 'num' to hold the number of integers

int main()
{
int i, x, min_num, result; // Declare variables for iteration, input, minimum value, and result

  // Prompt the user to enter the number of integers
printf("What is the number of integers you wish to input? ");

  // Read the number of integers from the user
scanf("%d", &num);

  // Prompt the user to input the numbers
printf("Input the number(s):\n");

  // Loop to read and count occurrences of each integer
for (i = 0; i<num; i++)
  {
    // Read an integer from the user
scanf("%d", &x);

    // Increment the count of occurrences for the input integer
ctr[x]++;
  }

min_num = 100; // Initialize 'min_num' to a large value for comparison

  // Loop to find the smallest integer with non-zero occurrences
for (i = 1; i<= 100; i++)
  {
    // Check if the count of occurrences is non-zero and smaller than 'min_num'
if (ctr[i] > 0 &&ctr[i] <min_num)
    {
result = i; // Update 'result' with the current integer
min_num = ctr[i]; // Update 'min_num' with the current count
    }
  }

  // Print the smallest integer among the input integers
printf("Smallest among the said integers: %d\n", result);

  // Return 0 to indicate successful program execution
return 0;
}

#include <stdio.h> // Include standard input/output library
#include <string.h> // Include string handling library

int main(void)
{
char text[101] = {0}; // Declare an array 'text' to hold the input string
char result[101] = {0}; // Declare an array 'result' to hold the modified string
int n1, n2, l; // Declare variables for position inputs and string length

    // Prompt the user to input a string
printf("Input a string: ");

    // Read the input string from the user and store it in the 'text' array
scanf("%s", text);

    // Prompt the user to input position-1 for reversing the string
printf("Input position-1 for reverse the string: ");

    // Read the position-1 input from the user and store it in 'n1'
scanf("%d", &n1);

    // Prompt the user to input position-2 for reversing the string
printf("\nInput position-2 for reverse the string: ");

    // Read the position-2 input from the user and store it in 'n2'
scanf("%d", &n2);

    l = strlen(text); // Calculate the length of the input string and store it in 'l'
int i = 0;

    // Copy characters from the start of 'text' to 'result' until position-1
for(; i< n1-1; i++) {
result[i] = text[i];
    }

    // Reverse and copy characters from position-2 to position-1 in 'text' to 'result'
for(int j = n2-1; i< n2; i++, j--) {
result[i] = text[j];
    }

    // Copy the remaining characters from 'text' to 'result'
for(; i<= l; i++) {
result[i] = text[i];
    }

    // Print the modified string
printf("Reverse string (partly): %s\n", result);

return 0;
}

#include <stdio.h> // Include standard input/output library

int test(int x, int y); // Declare the function 'test' with two integer parameters

int main(void)
{
    // Call the function 'test' with arguments 1 and 2 and print the result
    printf("%d", test(1, 2));

    // Print a newline for formatting
    printf("\n");

    // Call the function 'test' with arguments 2 and 2 and print the result
    printf("%d", test(2, 2));
}
// Function definition for 'test'
int test(int x, int y)
{
    // Conditional expression: If x is equal to y, return (x + y) multiplied by 3, otherwise return x + y
    return x == y ? (x + y) * 3 : x + y;
}

#include <stdio.h> // Include standard input/output library

int test(int n); // Declare the function 'test' with an integer parameter

int main(void)
{
    // Call the function 'test' with argument 53 and print the result
    printf("%d", test(53));

    // Print a newline for formatting
    printf("\n");

    // Call the function 'test' with argument 30 and print the result
    printf("%d", test(30));

    // Print a newline for formatting
    printf("\n");

    // Call the function 'test' with argument 51 and print the result
    printf("%d", test(51));
}

// Function definition for 'test'
int test(int n)
{
    const int x = 51; // Declare and initialize constant variable 'x'

    if (n > x) // Check if 'n' is greater than 'x'
    {
        return (n - x) * 3; // Return the result of the expression (n - x) multiplied by 3
    }

    return x - n; // Return the result of the expression x minus n
}

