}

#include <stdio.h>     // Include the standard input/output header file.

float myradius;          /* radius of the sphere */
float myvolume;          /* volume of the sphere (to be computed) */
char line_text[50];      /* a line from the keyboard */

/* the value of pi to 50 places, from wikipedia */
const float PI = 3.14159265358979323846264338327950288419716939937510;

int main() {
printf("Input the radius of the sphere : ");  // Prompt the user to input the radius of the sphere.
fgets(line_text, sizeof(line_text), stdin);  // Read a line of input from the user and store it in 'line_text'.
sscanf(line_text, "%f", &myradius);         // Convert the input from 'line_text' to a float and store it in 'myradius'.

myvolume = (4.0 / 3.0) * PI * (myradius * myradius * myradius);  /* Calculate the volume of the sphere using the formula. */
printf("The volume of sphere is %f.\n", myvolume);  // Print the calculated volume of the sphere.

return(0);   // Return 0 to indicate successful execution of the program.
}

#include <stdio.h>

int main() {
    int i = 0;  // Initialize the loop counter

    // First while loop: Print numbers from 0 to 10
    printf("Numbers from 0 to 10:\n");
    while (i <= 10) {
        printf("%d ", i);  // Print the current value of i
        i++;  // Increment the loop counter
    }

    printf("\n");  // Move to the next line for better formatting

    i = 10;  // Reset the loop counter to 10

    // Second while loop: Print numbers from 10 to 0
    printf("\nNumbers from 10 to 0:\n");
 while (i >= 0) {
        printf("%d ", i);  // Print the current value of i
        i--;  // Decrement the loop counter
    }

    return 0;  // Indicate successful program execution
}

#include <stdio.h>

 int main() {
    int number;  // Variable to store the user input
    int sum = 0;  // Variable to store the sum of positive integers

    printf("Input integers (enter 0 to stop):\n");

    // Start a while loop to continue until the user enters 0
    while (1) {
        printf("Input a number: ");
        scanf("%d", &number);  // Read the user input

        if (number == 0) {
            break;  // Exit the loop if the user enters 0
        }

        if (number > 0) {
            sum += number;  // Add positive numbers to the sum
        }
    }

    // Print the sum of positive integers
    printf("Sum of positive integers: %d\n", sum);

    return 0;  // Indicate successful program execution
}

#include <stdio.h>

int main() {
    int i = 1;  // Initialize the loop control variable to 1

    // Print numbers from 1 to 10
    printf("Print numbers from 1 to 10:\n");
    do {
        printf("%d ", i);  // Print the current value of i
        i++;  // Increment i for the next iteration
    } while (i <= 10);  // Continue the loop as long as i is less than or equal to 10

    printf("\n");  // Move to the next line for better formatting

    i = 10;  // Reset i to 10 for the second part of the program

    // Print numbers from 10 to 1
    printf("\nPrint numbers from 10 to 1:\n");
    do {
        printf("%d ", i);  // Print the current value of i
        i--;  // Decrement i for the next iteration
    } while (i >= 1);  // Continue the loop as long as i is greater than or equal to 1

    return 0;  // Indicate successful program execution
}

#include <stdio.h>

int main() {
    int num, sum = 0;  // Declare variables to store the entered number and the sum

    // Prompt the user to input integers until they enter 0
    do {
        printf("Input an integer (enter 0 to stop): ");
        scanf("%d", &num);  // Read the entered number

        if (num > 0) {
            sum += num;  // Add the positive number to the sum
        } else if (num < 0) {
            printf("Negative integers are not considered. Ignored.\n");
        }

    } while (num != 0);  // Continue the loop until the user enters 0

    // Print the sum of positive integers
    printf("Sum of positive integers: %d\n", sum);

    return 0;  // Indicate successful program execution
}

