    time(&now); // Get the current time

    struct tm beg_month; // Structure to hold the beginning of the month's date and time
    beg_month = *localtime(&now); // Retrieve local time
    beg_month.tm_hour = 0; // Set hours to 0
    beg_month.tm_min = 0; // Set minutes to 0
    beg_month.tm_sec = 0; // Set seconds to 0
    beg_month.tm_mday = 1; // Set day to 1 (beginning of the month)

    double seconds = difftime(now, mktime(&beg_month)); // Calculate the difference between the current time and the beginning of the month
    printf("\n %.f seconds passed since the beginning of the month.\n\n", seconds); // Print the seconds elapsed since the beginning of the month
    return 0;
}

#include <stdio.h>

// Function to reverse the digits of an integer
int reverse(int n) {
    int d, y = 0;

    // Reversing the digits of the integer
    while (n) {
        d = n % 10;

        // Check for potential overflow before updating the reversed integer
        if ((n > 0 && y > (0x7fffffff - d) / 10) ||
            (n < 0 && y < ((signed)0x80000000 - d) / 10)) {
            return 0;  // Return 0 if overflow detected
        }

        y = y * 10 + d;  // Update the reversed integer
        n = n / 10;      // Move to the next digit
    }

    return y;  // Return the reversed integer
}

int main(void)
{
    int i = 123;
    printf("Original integer: %d  ", i);
    printf("\nReverse integer: %d  ", reverse(i));

    i = 208478933;
    printf("\nOriginal integer: %d  ", i);
    printf("\nReverse integer: %d  ", reverse(i));

    i = -73634;
    printf("\nOriginal integer: %d  ", i);
    printf("\nReverse integer: %d  ", reverse(i));

    return 0;
}

#include <stdio.h>
#include <stdbool.h>

// Function to check if a number is a palindrome
bool is_Palindrome(int i) {
    int n, d, y = 0;

    // Check if the number is negative; negative numbers cannot be palindromes
    if (i < 0) 
        return false;

    n = i;
    // Reverse the number and compare it with the original number
    while (n) {
        d = n % 10;

        // Check for potential overflow
        if (y > (0x7fffffff - d) / 10) 
            return false;   // Return false if overflow is detected

        y = y * 10 + d;  // Reverse the number
        n = n / 10;      // Move to the next digit
    }

    return (y == i);  // Return true if the reversed number is equal to the original number
}

int main(void)
{
    int i = 1221;
    printf("Original integer: %d  ", i);
    printf("\nIs Palindrome: %d  ", is_Palindrome(i));

    i = -121;
    printf("\nOriginal integer: %d  ", i);
    printf("\nIs Palindrome: %d  ", is_Palindrome(i));

    i = 100;
    printf("\nOriginal integer: %d  ", i);
    printf("\nIs Palindrome: %d  ", is_Palindrome(i));

    return 0;
}

